package manager

func addArtifactPublicationPaths(doc map[string]any) {
	paths, ok := doc["paths"].(map[string]any)
	if !ok {
		paths = map[string]any{}
		doc["paths"] = paths
	}
	publicationPathParam := map[string]any{
		"name":        "publication_id",
		"in":          "path",
		"required":    true,
		"schema":      map[string]string{"type": "string"},
		"description": "Artifact publication identifier generated by paxd.",
	}
	nodePublicationPath := map[string]any{
		"put": map[string]any{
			"tags":        []string{"node"},
			"summary":     "Register an agent artifact publication",
			"description": "Idempotently registers a publication for an agent session owned by the authenticated node.",
			"security":    []map[string][]string{{"nodeBearer": {}}},
			"parameters":  []map[string]any{publicationPathParam},
			"responses": map[string]any{
				"200": map[string]string{"description": "Registered publication."},
				"400": map[string]string{"description": "Invalid publication metadata."},
				"401": map[string]string{"description": "Node authentication failed."},
				"404": map[string]string{"description": "Agent or session not found on this node."},
				"409": map[string]string{
					"description": "Publication identifier is already bound to another source.",
				},
			},
		},
	}
	nodePublicationPath["post"] = map[string]any{
		"tags":        []string{"node"},
		"summary":     "Prepare an agent artifact upload",
		"description": "Reuses the natural file identity when possible and otherwise returns a direct S3-compatible presigned PUT ticket. If PUT returns HTTP 412, the object may be the result of an earlier upload whose response was lost; call the completion endpoint and let its HEAD integrity validation decide. Other 4xx responses are upload failures.",
		"security":    []map[string][]string{{"nodeBearer": {}}},
		"parameters":  []map[string]any{publicationPathParam},
		"responses": map[string]any{
			"200": map[string]string{"description": "Upload ticket or already-available artifact."},
			"400": map[string]string{"description": "Invalid file identity."},
			"401": map[string]string{"description": "Node authentication failed."},
			"404": map[string]string{"description": "Publication not found on this node."},
			"409": map[string]string{
				"description": "Publication metadata conflicts with the file identity.",
			},
		},
	}
	paths[openAPINodeArtifactPublication] = nodePublicationPath
	addUserObjectUploadPaths(paths)
	paths[openAPINodeArtifactUploadComplete] = map[string]any{
		"post": map[string]any{
			"tags":        []string{"node"},
			"summary":     "Complete an agent artifact upload",
			"description": "Verifies immutable object metadata and makes all matching publications available.",
			"security":    []map[string][]string{{"nodeBearer": {}}},
			"parameters": []map[string]any{{
				"name": "upload_id", "in": "path", "required": true,
				"schema": map[string]string{"type": "string"},
			}},
			"responses": map[string]any{
				"200": map[string]string{"description": "Available artifact."},
				"401": map[string]string{"description": "Node authentication failed."},
				"404": map[string]string{"description": "Upload not found on this node."},
				"409": map[string]string{
					"description": "Uploaded object failed integrity validation.",
				},
			},
		},
	}
	paths[openAPINodeArtifactFailure] = map[string]any{
		"post": map[string]any{
			"tags":        []string{"node"},
			"summary":     "Report a permanent agent artifact failure",
			"description": "Marks a non-finalized publication failed without downgrading an available artifact.",
			"security":    []map[string][]string{{"nodeBearer": {}}},
			"parameters":  []map[string]any{publicationPathParam},
			"responses": map[string]any{
				"200": map[string]string{"description": "Failed or already-available publication."},
				"400": map[string]string{"description": "Invalid permanent failure."},
				"401": map[string]string{"description": "Node authentication failed."},
				"404": map[string]string{"description": "Publication not found on this node."},
				"409": map[string]string{
					"description": "A different permanent failure was already recorded.",
				},
			},
		},
	}
	paths[openAPIUserArtifactPublication] = map[string]any{
		"get": map[string]any{
			"tags":        []string{"user"},
			"summary":     "Get an artifact publication",
			"description": "Returns publication state when it belongs to the authenticated user.",
			"security":    []map[string][]string{{"cloudflareAccess": {}}},
			"parameters": []map[string]any{
				{
					"name":        "user_id",
					"in":          "path",
					"required":    true,
					"schema":      map[string]string{"type": "string"},
					"description": "User identifier or self.",
				},
				publicationPathParam,
			},
			"responses": map[string]any{
				"200": map[string]string{"description": "Artifact publication."},
				"401": map[string]string{"description": "User authentication failed."},
				"404": map[string]string{"description": "Artifact publication not found."},
			},
		},
	}
	paths[openAPIUserArtifactContent] = map[string]any{
		"get": map[string]any{
			"tags":        []string{"user"},
			"summary":     "Preview or download published artifact content",
			"description": "Resolves publication state and signs generation-pinned content using the safe inline preview policy.",
			"security":    []map[string][]string{{"cloudflareAccess": {}}},
			"parameters": []map[string]any{
				{
					"name": "user_id", "in": "path", "required": true,
					"schema": map[string]string{"type": "string"},
				},
				publicationPathParam,
				{
					"name": "content_ref", "in": "path", "required": true,
					"schema": map[string]string{"type": "string"},
				},
				{
					"name": "disposition", "in": "query",
					"schema": map[string]any{
						"type": "string",
						"enum": []string{"inline", "attachment"},
					},
				},
				{
					"name": "redirect", "in": "query",
					"schema": map[string]string{"type": "boolean"},
				},
			},
			"responses": map[string]any{
				"200": map[string]string{"description": "Signed immutable artifact content."},
				"202": map[string]string{
					"description": "Publication is not available yet and may be retried.",
				},
				"401": map[string]string{"description": "User authentication failed."},
				"404": map[string]string{"description": "Publication or content not found."},
				"409": map[string]string{
					"description": "Publication failed or content is not finalized.",
				},
			},
		},
	}
}

func addUserObjectUploadPaths(paths map[string]any) {
	userParameter := map[string]any{
		"name":        "user_id",
		"in":          "path",
		"required":    true,
		"schema":      map[string]string{"type": "string"},
		"description": "User ID or self.",
	}
	uploadProtocol := "Returns an s3_presigned_put ticket. Send every ticket header with the PUT. HTTP 412 is ambiguous already-exists and must be followed by completion so HEAD integrity validation can decide; other 4xx responses are failures."
	completeProtocol := "Uses HEAD to validate the object written through the presigned ticket. This is also the recovery step after an ambiguous HTTP 412 from PUT."
	paths["/api/v1/user/{user_id}/artifact-uploads"] = map[string]any{
		"post": map[string]any{
			"tags":        []string{"artifacts"},
			"summary":     "Prepare a user artifact upload",
			"description": uploadProtocol,
			"security":    []map[string][]string{{"cloudflareAccess": {}}},
			"parameters":  []map[string]any{userParameter},
			"responses": map[string]any{
				"200": map[string]string{"description": "Presigned PUT ticket."},
				"400": map[string]string{"description": "Invalid upload metadata."},
				"401": map[string]string{"description": "User authentication failed."},
			},
		},
	}
	paths["/api/v1/user/{user_id}/artifact-uploads/{upload_id}/complete"] = map[string]any{
		"post": map[string]any{
			"tags":        []string{"artifacts"},
			"summary":     "Complete a user artifact upload",
			"description": completeProtocol,
			"security":    []map[string][]string{{"cloudflareAccess": {}}},
			"parameters": []map[string]any{userParameter, {
				"name": "upload_id", "in": "path", "required": true,
				"schema": map[string]string{"type": "string"},
			}},
			"responses": map[string]any{
				"200": map[string]string{"description": "Completed artifact."},
				"404": map[string]string{"description": "Upload not found."},
				"409": map[string]string{"description": "Object integrity validation failed."},
			},
		},
	}
}
